.venv/bin/python -c "import pandas as pd; import numpy as np; df=pd.read_csv('train.csv'); best_acc=0; best_feat=''; 
for col in df.columns[:-1]:
    for thresh in np.linspace(df[col].min(), df[col].max(), 50):
        pred = (df[col] > thresh).astype(int)
        acc = (pred == df['target']).mean()
        acc = max(acc, 1-acc)
        if acc > best_acc: best_acc=acc; best_feat=col
print(f'Best train acc: {best_acc} with {best_feat}')"

